from datetime import datetime
from typing import Dict, List, Optional

from pydantic import BaseModel, Field, model_validator, field_validator, RootModel
from pydantic_settings import BaseSettings


class Settings(BaseSettings):
    currency: str = "USD"
    tax_rate: float = 0.18

    class Config:
        env_prefix = "SHOP_"


class Product(BaseModel):
    sku: str = Field(..., pattern=r"^[A-Z]{3}-\d{4}$")
    name: str
    price_cents: int = Field(..., gt=0)
    tags: List[str] = []
    discontinued: Optional[bool] = None

    class Config:
        str_strip_whitespace = True
        frozen = True

    @field_validator("tags")
    def lower_tags(cls, v):
        return [t.lower() for t in v]


class LineItem(BaseModel):
    product: Product
    quantity: int = Field(1, ge=1)

    @property
    def total_cents(self) -> int:
        return self.product.price_cents * self.quantity


class Order(BaseModel):
    kind: str = Field("order")
    id: int
    items: List[LineItem]
    coupon: Optional[str] = Field(None, alias="couponCode")
    created_at: datetime = Field(default_factory=datetime.utcnow)

    class Config:
        from_attributes = True
        populate_by_name = True

    @model_validator(mode='before')
    def no_empty_orders(cls, values):
        # Handle both dict and object
        if isinstance(values, dict):
            items = values.get("items")
        else:
            items = getattr(values, "items", None)
        if not items:
            raise ValueError("an order needs at least one item")
        return values

    @model_validator(mode='after')
    def _constant_kind(self):
        if self.kind != "order":
            raise ValueError("kind must be 'order'")
        return self

    def subtotal_cents(self) -> int:
        return sum(i.total_cents for i in self.items)


class Inventory(RootModel[Dict[str, int]]):
    def count(self, sku: str) -> int:
        return self.root.get(sku, 0)
